/**
 * Save outgoing_cost.csv & build ThingSpeak sequence
 *
 * Body of the Node-RED function node `0612400ed25dc8c0` in flows.json,
 * wired with 2 outputs.
 * It runs inside Node-RED with `msg`, `node`, `flow` and `global` in scope,
 * which is why it reads as a bare body rather than a module.
 *
 * Generated by tools/extract-functions.js — edit the flow, not this file.
 */

// we order only for ThingSpeak.

var costRows = flow.get('outgoing_cost_rows') || [];

function hexVal(x) {
    return parseInt(String(x).trim(), 16);
}

// CSV written based on the arrival order (no reordering)
var lines = 'No.,Source,Destination,Cost\n';
for (var i = 0; i < costRows.length; i++) {
    var r = costRows[i];
    lines += (i + 1) + ',' + r.src + ',' + r.dst + ',' + r.cost + '\n';
}

var csvMsg = {
    payload: lines,
    filename: './challenge3_output/outgoing_cost.csv'
};
node.status({fill:'green', shape:'dot', text:'outgoing_cost.csv ready (' + costRows.length + ' rows)'});

// for ThingSpeak: smallest source + dest ascending hex 
if (costRows.length === 0) {
    node.warn('No link status data collected. outgoing_cost.csv has only the header.');
    return [csvMsg, null];
}

// find the smallest source (treat as hex)
var sourcesSeen = {};
for (var s = 0; s < costRows.length; s++) {
    sourcesSeen[costRows[s].src] = true;
}
var srcList = Object.keys(sourcesSeen);
srcList.sort(function(a, b) { return hexVal(a) - hexVal(b); });
var smallestSrc = srcList[0];

// all the rows of the smallestSrc ordered for dest hex ascending
var rowsForSmallest = costRows.filter(function(r) { return r.src === smallestSrc; });
rowsForSmallest.sort(function(a, b) { return hexVal(a.dst) - hexVal(b.dst); });

var sequence = [];
for (var j = 0; j < rowsForSmallest.length; j++) {
    sequence.push({ dst: rowsForSmallest[j].dst, cost: rowsForSmallest[j].cost });
}

var tsMsg = {payload: sequence, _smallest_src: smallestSrc};
return [csvMsg, tsMsg];
